"use client";

import {
  ArrowClockwiseIcon,
  PaperclipIcon,
  ShareNetworkIcon,
  SparkleIcon,
} from "@phosphor-icons/react";
import { useEffect, useRef, useState } from "react";
import { AgentStatus } from "../../../components/vip-ui/agent-status";
import { Attachment, AttachmentList } from "../../../components/vip-ui/attachment";
import { Badge } from "../../../components/vip-ui/badge";
import { Button } from "../../../components/vip-ui/button";
import { CopyButton } from "../../../components/vip-ui/copy-button";
import { Kbd } from "../../../components/vip-ui/kbd-code";
import { Message } from "../../../components/vip-ui/message";
import {
  PromptInput,
  PromptInputFooter,
  PromptInputSubmit,
  PromptInputTextArea,
} from "../../../components/vip-ui/prompt-input";
import {
  Reasoning,
  ReasoningPanel,
  ReasoningTrigger,
} from "../../../components/vip-ui/reasoning";
import {
  Response,
  ResponseActions,
  ResponseContent,
  ResponseFooter,
  ResponseNotice,
} from "../../../components/vip-ui/response";
import { Select } from "../../../components/vip-ui/select";
import { Skeleton } from "../../../components/vip-ui/skeleton";
import { SourceLink } from "../../../components/vip-ui/source-link";
import { showToast } from "../../../components/vip-ui/toast";
import {
  ToolCall,
  ToolCallCode,
  ToolCallPanel,
  ToolCallSection,
  ToolCallTrigger,
} from "../../../components/vip-ui/tool-call";
import {
  assistantAvatarLabel,
  type ChatTurn,
  initialTurn,
  modelOptions,
  starterPrompts,
  turnFor,
  turnText,
} from "./data";

interface FileItem {
  id: number;
  name: string;
  size: number;
  status: "uploading" | "complete";
}

const initialFiles: FileItem[] = [
  {
    id: 1,
    name: "activation-week.png",
    size: 184320,
    status: "complete",
  },
];

export function AssistantChat() {
  const [turns, setTurns] = useState<ChatTurn[]>([initialTurn]);
  const [draft, setDraft] = useState("");
  const [model, setModel] = useState("fast");
  const [files, setFiles] = useState<FileItem[]>(initialFiles);
  const scrollRef = useRef<HTMLDivElement>(null);
  const timer = useRef<number | null>(null);
  const previousTurns = useRef(
    turns.map((turn) => `${turn.id}:${turn.status}`).join("|"),
  );
  const modelName = modelOptions.find((option) => option.id === model)?.name;

  useEffect(() => {
    const key = turns.map((turn) => `${turn.id}:${turn.status}`).join("|");
    if (key === previousTurns.current) return;
    previousTurns.current = key;
    const element = scrollRef.current;
    element?.scrollTo({ top: element.scrollHeight, behavior: "smooth" });
  }, [turns]);

  useEffect(
    () => () => {
      if (timer.current !== null) window.clearTimeout(timer.current);
    },
    [],
  );

  function finish(id: string) {
    if (timer.current !== null) window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => {
      setTurns((current) =>
        current.map((turn) =>
          turn.id === id ? { ...turn, status: "complete" } : turn,
        ),
      );
      timer.current = null;
    }, 1700);
  }

  function send(value: string) {
    const prompt = value.trim();
    if (!prompt || turns.some((turn) => turn.status === "pending")) return;
    const id = crypto.randomUUID();
    const turn = turnFor(
      id,
      prompt,
      files.map((file) => file.name),
    );
    setTurns((current) => [...current, turn]);
    setDraft("");
    setFiles([]);
    finish(id);
  }

  function stop() {
    if (timer.current !== null) window.clearTimeout(timer.current);
    timer.current = null;
    setTurns((current) =>
      current.map((turn) =>
        turn.status === "pending" ? { ...turn, status: "stopped" } : turn,
      ),
    );
  }

  function regenerate(id: string) {
    setTurns((current) =>
      current.map((turn) =>
        turn.id === id ? { ...turn, status: "pending" } : turn,
      ),
    );
    finish(id);
  }

  function addFiles(selected: File[]) {
    const added = selected.map((file, index) => ({
      id: Date.now() + index,
      name: file.name,
      size: file.size,
      status: "uploading" as const,
    }));
    setFiles((current) => [...current, ...added]);
    for (const file of added) {
      window.setTimeout(() => {
        setFiles((current) =>
          current.map((item) =>
            item.id === file.id
              ? { ...item, status: "complete" as const }
              : item,
          ),
        );
      }, 900);
    }
  }

  function openFilePicker() {
    const input = document.createElement("input");
    input.type = "file";
    input.multiple = true;
    input.addEventListener("change", () => {
      addFiles(Array.from(input.files ?? []));
    });
    input.click();
  }

  async function share(turn: ChatTurn) {
    try {
      await navigator.clipboard.writeText(
        `https://app.fernway.app/answers/${turn.id}`,
      );
      showToast({ title: "Answer link copied" });
    } catch {
      showToast({
        title: "Copy failed",
        description: "Copy the answer with the Copy button.",
        variant: "error",
      });
    }
  }

  const pending = turns.some((turn) => turn.status === "pending");
  const lastTurn = turns[turns.length - 1];
  const suggestions =
    lastTurn?.status === "complete"
      ? starterPrompts.filter((prompt) => prompt !== lastTurn.prompt)
      : [];

  return (
    <div className="flex h-svh min-h-[34rem] flex-col bg-background text-foreground">
      <header className="shrink-0 border-b border-border/70 bg-card/85 backdrop-blur">
        <div className="mx-auto flex w-full max-w-3xl items-center gap-3 px-4 py-3 sm:px-6">
          <span
            aria-hidden="true"
            className="grid size-9 shrink-0 place-items-center rounded-xl bg-primary text-primary-foreground shadow-[var(--shadow-card)]"
          >
            <SparkleIcon size={18} weight="fill" />
          </span>
          <div className="min-w-0 flex-1">
            <div className="flex items-center gap-2">
              <h1 className="truncate text-base font-semibold">Ask Fernway</h1>
              <Badge variant="outline" className="min-h-5 py-0 text-[10px]">
                Beta
              </Badge>
            </div>
            <p className="truncate text-xs text-muted-foreground">
              Answers with sources
            </p>
          </div>
          <Select
            aria-label="Model"
            size="sm"
            options={modelOptions}
            value={model}
            onValueChange={setModel}
            className="w-28 shrink-0"
          />
        </div>
      </header>

      <div
        ref={scrollRef}
        className="min-h-0 flex-1 overflow-y-auto overscroll-contain"
      >
        <div className="mx-auto grid w-full max-w-3xl gap-6 px-4 py-6 sm:px-6">
          <h2 className="sr-only">Conversation</h2>
          <div className="flex items-center gap-3 text-xs text-muted-foreground">
            <span className="h-px flex-1 bg-border/70" />
            <span>Today, Oct 30</span>
            <span className="h-px flex-1 bg-border/70" />
          </div>

          {turns.map((turn) => (
            <section
              key={turn.id}
              aria-label={`Conversation about ${turn.prompt}`}
              className="grid gap-4"
            >
              <Message
                sender="You"
                side="outgoing"
                timestamp={turn.time}
                status={turn.status === "pending" ? "Sending" : "Sent"}
                actions={
                  <CopyButton
                    value={turn.prompt}
                    variant="ghost"
                    iconOnly
                    size="xs"
                    aria-label="Copy your message"
                  />
                }
              >
                {turn.prompt}
                {turn.attachments.length > 0 && (
                  <span className="mt-2 flex flex-wrap gap-1.5">
                    {turn.attachments.map((name) => (
                      <span
                        key={name}
                        className="inline-flex max-w-full items-center gap-1.5 rounded-md bg-background/60 px-2 py-1 text-xs font-medium"
                      >
                        <PaperclipIcon size={12} aria-hidden="true" />
                        <span className="truncate">{name}</span>
                      </span>
                    ))}
                  </span>
                )}
              </Message>

              <div className="flex items-start gap-3">
                <span
                  aria-hidden="true"
                  className="grid size-8 shrink-0 place-items-center rounded-lg bg-primary text-primary-foreground shadow-[var(--shadow-card)]"
                >
                  <SparkleIcon size={15} weight="fill" />
                </span>
                <div className="grid min-w-0 flex-1 gap-3">
                  <p className="text-xs text-muted-foreground">
                    <span className="font-medium text-foreground">Fernway</span>
                    {turn.status === "pending"
                      ? " · Working"
                      : turn.status === "stopped"
                        ? " · Stopped"
                        : ` · Answered in ${turn.duration}s`}
                    {modelName ? ` · ${modelName}` : ""}
                  </p>

                  {turn.status === "pending" ? (
                    <>
                      <AgentStatus
                        state="working"
                        label="Checking product data"
                        detail="Reading activation events from the last 7 days"
                      />
                      <div className="grid gap-2 py-1" aria-hidden="true">
                        <Skeleton className="h-3 w-11/12" />
                        <Skeleton className="h-3 w-4/5" />
                        <Skeleton className="h-3 w-2/3" />
                      </div>
                    </>
                  ) : turn.status === "stopped" ? (
                    <Response status="stopped" className="w-full">
                      <ResponseContent>
                        Stopped before Fernway finished the answer.
                      </ResponseContent>
                      <ResponseNotice />
                      <ResponseActions>
                        <Button
                          variant="ghost"
                          size="sm"
                          onPress={() => regenerate(turn.id)}
                        >
                          <ArrowClockwiseIcon size={16} aria-hidden="true" />
                          Try again
                        </Button>
                      </ResponseActions>
                    </Response>
                  ) : (
                    <>
                      <Reasoning
                        status="complete"
                        duration={turn.duration}
                        className="w-full"
                      >
                        <ReasoningTrigger />
                        <ReasoningPanel>{turn.reasoning}</ReasoningPanel>
                      </Reasoning>

                      <ToolCall className="w-full">
                        <ToolCallTrigger
                          name={turn.tool.name}
                          status="complete"
                          summary={turn.tool.summary}
                        />
                        <ToolCallPanel>
                          <ToolCallSection label="Input">
                            <ToolCallCode>{turn.tool.input}</ToolCallCode>
                          </ToolCallSection>
                          <ToolCallSection label="Output">
                            <ToolCallCode>{turn.tool.output}</ToolCallCode>
                          </ToolCallSection>
                        </ToolCallPanel>
                      </ToolCall>

                      <Response status="complete" className="w-full">
                        <ResponseContent className="grid gap-3">
                          {turn.answer.map((block) => {
                            const key =
                              block.type === "paragraph"
                                ? block.text
                                : block.items.join("|");
                            return block.type === "paragraph" ? (
                              <p key={key}>{block.text}</p>
                            ) : (
                              <ul
                                key={key}
                                className="grid list-disc gap-1.5 ps-5 marker:text-muted-foreground"
                              >
                                {block.items.map((item) => (
                                  <li key={item}>{item}</li>
                                ))}
                              </ul>
                            );
                          })}
                        </ResponseContent>
                        <ResponseActions>
                          <CopyButton
                            value={turnText(turn)}
                            variant="ghost"
                            size="sm"
                          />
                          <Button
                            variant="ghost"
                            size="sm"
                            onPress={() => regenerate(turn.id)}
                          >
                            <ArrowClockwiseIcon size={16} aria-hidden="true" />
                            Regenerate
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onPress={() => void share(turn)}
                          >
                            <ShareNetworkIcon size={16} aria-hidden="true" />
                            Share
                          </Button>
                        </ResponseActions>
                        <ResponseFooter className="grid gap-2 pt-1">
                          <p className="text-xs font-medium text-muted-foreground">
                            Sources
                          </p>
                          {turn.sources.map((source, index) => (
                            <SourceLink
                              key={source.href}
                              href={source.href}
                              label={source.label}
                              source={source.source}
                              description={source.description}
                              index={index + 1}
                              className="gap-2.5 p-2.5"
                            />
                          ))}
                        </ResponseFooter>
                      </Response>
                    </>
                  )}
                </div>
              </div>
            </section>
          ))}

          {lastTurn?.status === "complete" && !pending && (
            <div className="flex flex-wrap items-center gap-2 ps-11">
              <span className="text-xs text-muted-foreground">Follow up</span>
              {suggestions.map((suggestion) => (
                <Button
                  key={suggestion}
                  variant="outline"
                  size="sm"
                  onPress={() => setDraft(suggestion)}
                >
                  {suggestion}
                </Button>
              ))}
            </div>
          )}
        </div>
      </div>

      <footer className="shrink-0 border-t border-border/70 bg-card/85 backdrop-blur">
        <div className="mx-auto w-full max-w-3xl px-4 pt-3 pb-[max(0.75rem,env(safe-area-inset-bottom))] sm:px-6">
          <PromptInput
            label="Message"
            size="md"
            placeholder="Ask about activation, revenue, or a customer"
            value={draft}
            onChange={setDraft}
            isPending={pending}
            onSubmit={send}
            onStop={stop}
            onFilesDropped={addFiles}
          >
            <PromptInputTextArea
              className="py-2.5"
              placeholder="Ask about activation, revenue, or a customer"
            />
            {files.length > 0 && (
              <AttachmentList className="px-2.5 pt-2.5">
                {files.map((file) => (
                  <Attachment
                    key={file.id}
                    name={file.name}
                    fileSize={file.size}
                    status={file.status}
                    className="gap-2 p-1.5 [&_[data-slot=attachment-details]]:text-[11px] [&_[data-slot=attachment-name]]:text-xs [&_[data-slot=attachment-preview]]:size-8"
                    onRemove={() =>
                      setFiles((current) =>
                        current.filter((item) => item.id !== file.id),
                      )
                    }
                  />
                ))}
              </AttachmentList>
            )}
            <PromptInputFooter>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                iconOnly
                aria-label="Attach files"
                onPress={openFilePicker}
              >
                <PaperclipIcon aria-hidden="true" />
              </Button>
              <span className="hidden items-center gap-1.5 text-xs text-muted-foreground sm:flex">
                <Kbd>Enter</Kbd> to send
              </span>
              <PromptInputSubmit className="ms-auto" />
            </PromptInputFooter>
          </PromptInput>
          <p className="mt-2 text-center text-[11px] leading-4 text-muted-foreground">
            {assistantAvatarLabel} can make mistakes. Check important numbers.
          </p>
        </div>
      </footer>
    </div>
  );
}

export type AnswerBlock =
  | { type: "paragraph"; text: string }
  | { type: "list"; items: string[] };

export interface ChatSource {
  label: string;
  source: string;
  href: string;
  description: string;
}

export interface ChatTurn {
  id: string;
  prompt: string;
  status: "complete" | "pending" | "stopped";
  time: string;
  attachments: string[];
  reasoning: string;
  duration: number;
  tool: {
    name: string;
    summary: string;
    input: string;
    output: string;
  };
  answer: AnswerBlock[];
  sources: ChatSource[];
}

export const assistantAvatarLabel = "Fernway Assistant";

export const modelOptions = [
  { id: "fast", name: "Fast" },
  { id: "deep", name: "Deep" },
];

export const starterPrompts = [
  "Why did activation drop last week?",
  "Compare activation with August",
  "Show the invite funnel",
];

export const initialTurn: ChatTurn = {
  id: "activation",
  prompt: "Why did activation drop last week?",
  status: "complete",
  time: "10:24 AM",
  attachments: [],
  reasoning:
    "Activation fell on Sep 24, one day after v2.14 shipped. I checked whether the new role picker blocks the invite path.",
  duration: 12,
  tool: {
    name: "query_events",
    summary: "Activation by week, Sep 15 to Oct 26",
    input: `{
  "metric": "activation",
  "from": "2026-09-15",
  "to": "2026-10-26",
  "segment": "all"
}`,
    output: `[
  { "week": "Sep 15", "activation": 61.8 },
  { "week": "Sep 22", "activation": 57.6 },
  { "week": "Sep 29", "activation": 57.1 },
  { "week": "Oct 6", "activation": 58.4 }
]`,
  },
  answer: [
    {
      type: "paragraph",
      text: "Activation fell from 61.8% to 57.6% after v2.14 added the role picker.",
    },
    {
      type: "list",
      items: [
        "The drop starts on Sep 24 and stays low.",
        "38% of invited users close the picker without a role.",
        "That rate was 9% before Sep 23.",
        "Invite completion lost 3.1 points, mostly on desktop.",
        "Android sign-ups lost 1.4 points after the new step.",
      ],
    },
    {
      type: "paragraph",
      text: "Next step: make the role optional for the first 7 days.",
    },
  ],
  sources: [
    {
      label: "Weekly activation report",
      source: "analytics.fernway.app · Oct 27",
      href: "https://analytics.fernway.app/reports/activation-weekly",
      description: "Activation by cohort, platform, and invite step.",
    },
    {
      label: "v2.14 release notes",
      source: "fernway.app/changelog · Sep 23",
      href: "https://fernway.app/changelog/v2-14",
      description: "Adds the role picker to the invite flow.",
    },
    {
      label: "Mobile sign-up funnel",
      source: "analytics.fernway.app · Oct 28",
      href: "https://analytics.fernway.app/reports/mobile-funnel",
      description: "Step-by-step drop-off for iOS and Android.",
    },
  ],
};

const tool = initialTurn.tool;

const sources = initialTurn.sources;

export function replyFor(prompt: string): Pick<ChatTurn, "answer" | "sources"> {
  const text = prompt.toLowerCase();
  if (text.includes("august") || text.includes("compare")) {
    return {
      answer: [
        {
          type: "paragraph",
          text: "Activation was 59.4% in August and is 57.6% today.",
        },
        {
          type: "list",
          items: [
            "The gap opens on Sep 24, after v2.14 shipped.",
            "August had no change to the invite step.",
            "September: 58.1% across 17,960 sign-ups.",
            "October: 57.9% across 16,240 sign-ups.",
          ],
        },
        {
          type: "paragraph",
          text: "Next step: make the role optional and watch activation for 7 days.",
        },
      ],
      sources: [sources[0], sources[2]],
    };
  }
  if (text.includes("android") || text.includes("mobile")) {
    return {
      answer: [
        {
          type: "paragraph",
          text: "Android invite completion is 39.8%, down from 44.6%.",
        },
        {
          type: "list",
          items: [
            "iOS is 47.1%, down 0.8 points.",
            "The Android sheet pushes the picker below the keyboard.",
            "Users close the sheet to reach the invite button.",
            "Desktop invite completion is 44.2%.",
          ],
        },
        {
          type: "paragraph",
          text: "Next step: move the role picker above the keyboard on Android.",
        },
      ],
      sources: [sources[2], sources[1]],
    };
  }
  if (text.includes("funnel") || text.includes("step")) {
    return {
      answer: [
        {
          type: "paragraph",
          text: "4,820 people were invited last week and 1,208 finished.",
        },
        {
          type: "list",
          items: [
            "Role picker opened: 3,140 users.",
            "Role selected: 1,950 users.",
            "Invite sent: 1,208 users.",
            "The picker loses 1,190 users, the largest drop.",
          ],
        },
        {
          type: "paragraph",
          text: "Next step: shorten the role picker step.",
        },
      ],
      sources: [
        {
          label: "Invite funnel, Sep 22 to Sep 28",
          source: "analytics.fernway.app · Oct 27",
          href: "https://analytics.fernway.app/reports/invite-funnel",
          description: "One row for each step in the invite flow.",
        },
        sources[2],
      ],
    };
  }
  return {
    answer: [
      {
        type: "paragraph",
        text: "The role picker still drives most of the change.",
      },
      {
        type: "list",
        items: [
          "Desktop invite completion: 44.2%.",
          "Android invite completion: 39.8%.",
          "iOS invite completion: 47.1%.",
          "Users who skip the role picker complete at 68.4%.",
        ],
      },
      {
        type: "paragraph",
        text: "Next step: make the role optional and measure activation.",
      },
    ],
    sources: [sources[0], sources[2]],
  };
}

export function turnFor(
  id: string,
  prompt: string,
  attachments: string[],
): ChatTurn {
  const reply = replyFor(prompt);
  return {
    id,
    prompt,
    status: "pending",
    time: "Just now",
    attachments,
    reasoning:
      "I should compare the same funnel with the week before and check the role picker step. The release notes and the mobile funnel give the context for the change.",
    duration: 9,
    tool,
    answer: reply.answer,
    sources: reply.sources,
  };
}

export function turnText(turn: ChatTurn) {
  return turn.answer
    .map((block) =>
      block.type === "paragraph"
        ? block.text
        : block.items.map((item) => `- ${item}`).join("\n"),
    )
    .join("\n\n");
}

import { AssistantChat } from "./chat";

export const metadata = {
  title: "Assistant chat",
  description: "Assistant chat that reads metrics and cites its sources.",
};

export default function ChatBlockPage() {
  return <AssistantChat />;
}
